'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>'฿'+Number(v||0).toLocaleString('th-TH',{maximumFractionDigits:2});
const count=v=>Number(v||0).toLocaleString('th-TH');
const localDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const date=v=>v?new Date(String(v).slice(0,10)+'T12:00:00').toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'numeric'}):'ยังไม่ระบุ';
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87',calendar:'M5 5h14a2 2 0 0 1 2 2v13H3V7a2 2 0 0 1 2-2 M7 3v4 M17 3v4 M3 11h18 M7 15h2 M13 15h2',heart:'M20 4a5 5 0 0 0-8 2 5 5 0 0 0-8-2c-5 5 8 15 8 15S25 9 20 4 M3 12h5l2-3 3 6 2-3h6',gift:'M3 8h18v4H3z M5 12v9h14v-9 M12 8v13 M12 8S5 8 5 4c0-4 7 0 7 4 M12 8s7 0 7-4c0-4-7 0-7 4',box:'M3 7l9-5 9 5v10l-9 5-9-5z M3 7l9 5 9-5 M12 12v10 M7 4l10 6',wallet:'M3 6h17v15H3z M3 6l14-4v4 M15 12h7v5h-7z M18 14h1',coins:'M12 3c5 0 8 2 8 4s-3 4-8 4-8-2-8-4 3-4 8-4 M4 7v5c0 2 3 4 8 4s8-2 8-4V7 M4 12v5c0 2 3 4 8 4s8-2 8-4v-5',shield:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6z M8 12l3 3 5-6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4 M12 14v3',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',logout:'M9 3H3v18h6 M9 12h12 M16 7l5 5-5 5',bell:'M5 17V9a7 7 0 0 1 14 0v8l2 2H3z M9 22h6',chevron:'M9 5l7 7-7 7',down:'M6 9l6 6 6-6',close:'M6 6l12 12 M18 6 6 18',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 12h8 M8 16h8',check:'M4 12l5 5L20 6',menu:'M3 6h18 M3 12h18 M3 18h18',camera:'M3 7h4l2-3h6l2 3h4v14H3z M12 10a4 4 0 1 0 0 8 4 4 0 0 0 0-8',trend:'M3 17l6-6 4 4 8-11 M15 4h6v6'};
const icon=(name)=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[name]||icons.file}"/></svg>`;
const NAV=[['dashboard','ภาพรวม','grid','OVERVIEW'],['patients','ผู้รับบริการ / เวชระเบียน','users','CLINIC MANAGEMENT'],['appointments','นัดหมาย & คิวแพทย์','calendar'],['procedures','บันทึกหัตถการ','heart'],['packages','คอร์ส & สมาชิก','gift'],['inventory','คลังสินค้า','box'],['finance','การเงิน & เอกสาร','wallet','BUSINESS'],['fees','ค่ามือ & คอมมิชชัน','coins'],['users','ผู้ใช้งาน & สิทธิ์','shield','ADMINISTRATION'],['audit','ประวัติการใช้งาน','clock'],['privacy','ความเป็นส่วนตัว / PDPA','lock']];
let me=null,view='dashboard',cache={},tab='',page=1,query='',filter='',month=localDate().slice(0,7),currentPatient=null,formHandler=null,toastTimer,routeVersion=0;
let lockTimer,lockDeadline=0;
function armLock(){if(!me)return;lockDeadline=Math.min(Date.now()+1800000,(me.expires_at||Date.now()/1000+28800)*1000);clearTimeout(lockTimer);lockTimer=setTimeout(lockWorkspace,Math.max(0,lockDeadline-Date.now()))}
async function lockWorkspace(){if(!me)return;me=null;cache={};currentPatient=null;formHandler=null;routeVersion++;$('#modal').close();$('#modal').innerHTML='';$('#print').innerHTML='';$('#app').innerHTML='<div class="loading">YUNA<span>CLINIC</span></div>';try{await auth();toast('เซสชันหมดอายุ กรุณาเข้าสู่ระบบอีกครั้ง')}catch(e){toast(e.message)}}
async function api(path,data){
 const res=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':me?.csrf||''},body:data===undefined?undefined:JSON.stringify(data)});
 const result=await res.json();
 if(!res.ok){if(res.status===401&&!['login','setup','me'].includes(path)){me=null;cache={};currentPatient=null;$('#modal').close();$('#modal').innerHTML='';$('#print').innerHTML='';await auth();}throw new Error(result.error||'ไม่สามารถทำรายการได้');}if(me)armLock();return result;
}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800)}
function pill(text,type=''){return `<span class="pill ${type}">${esc(text)}</span>`}
function status(v){return pill(v,({'ยืนยันแล้ว':'blue','เสร็จสิ้น':'green','กำลังรับบริการ':'gold','ยกเลิก':'red','รอพบแพทย์':'gold','ยินยอม':'green','ถอนความยินยอม':'red'})[v]||'')}
function btn(label,act,extra='',kind=''){return `<button class="${kind}" data-act="${act}" ${extra}>${label}</button>`}
function brand(){return '<div class="brand"><div class="clinic-logo"><img src="/yuna-logo.png" alt="Yuna Clinic" width="1825" height="2199" fetchpriority="high"></div></div>'}
async function auth(){
 const s=await api('status');const setup=s.setup;
 $('#app').innerHTML=`<main class="auth"><section class="auth-left">${brand()}<div class="eyebrow">YUNA CLINIC</div><h1><span class="slogan-intro">YOU...BUT MORE</span><br><em>STUNNING THAN EVER</em></h1><p>พื้นที่ทำงานสำหรับทีม Yuna Clinic<br>เชื่อมการดูแลผู้รับบริการและการบริหารไว้ด้วยกัน</p><div class="auth-detail"><span>${icon('shield')} สิทธิ์ตามบทบาท</span><span>${icon('lock')} ข้อมูลเฉพาะผู้ได้รับสิทธิ์</span></div></section><section class="auth-right"><form id="auth-form" class="authform"><div class="eyebrow">YUNA CLINIC WORKSPACE</div><h2>${setup?'เริ่มต้นพื้นที่ทำงาน':'ยินดีต้อนรับกลับ'}</h2><p>${setup?'สร้างบัญชี Owner สำหรับดูแลคลินิกและเพิ่มบัญชีทีมงาน':'เข้าสู่ระบบเพื่อเริ่มต้นวันทำงานของคุณ'}</p>${setup?field('name','ชื่อผู้ดูแล'):''}${setup&&s.setup_token_required?field('setup_token','รหัสตั้งค่า Owner จากผู้ดูแลระบบ','password','',{autocomplete:'off'}):''}${field('username','ชื่อผู้ใช้','text','',{autocomplete:'username'})}${field('password','รหัสผ่าน','password','',{autocomplete:setup?'new-password':'current-password',minlength:setup?12:1})}<div class="error" id="auth-error" role="alert"></div><button class="primary" type="submit">${setup?'สร้างบัญชีและเริ่มใช้งาน':'เข้าสู่ระบบ'} ${icon('arrow')}</button><div class="checknote">${setup?'รหัสผ่านอย่างน้อย 12 ตัวอักษร • ไม่มีบัญชีเริ่มต้นที่ตั้งรหัสผ่านไว้':'หากลืมรหัสผ่าน ติดต่อผู้ดูแล Owner ของคลินิก'}</div><div class="secure" style="margin-top:35px">${icon('shield')} การใช้งานถูกบันทึกเพื่อการตรวจสอบ</div></form></section></main>`;
 $('#auth-form').onsubmit=async e=>{e.preventDefault();const button=$('button[type=submit]',e.target);button.disabled=true;try{await api(setup?'setup':'login',Object.fromEntries(new FormData(e.target)));await boot();}catch(err){$('#auth-error').textContent=err.message;button.disabled=false;}};
}
async function boot(){try{me=await api('me');armLock();shell();await loadView('dashboard')}catch(e){if(!me){try{await auth()}catch(error){$('#app').innerHTML='<main class="auth-right" style="min-height:100vh"><section class="authform">'+brand()+'<h2>ยังไม่พร้อมเชื่อมต่อระบบ</h2><p>'+esc(error.message)+'</p><p class="checknote">ผู้ดูแลสามารถตรวจการตั้งค่าฐานข้อมูลใน Vercel แล้วลองใหม่</p>'+btn('ลองอีกครั้ง','retry')+'</section></main>'}}else toast(e.message)}}
function shell(){
 $('#app').innerHTML=`<aside class="sidebar">${brand()}<nav>${NAV.filter(n=>me.views.includes(n[0])).map(n=>`${n[3]?`<div class="navlabel">${n[3]}</div>`:''}<button class="navitem" data-view="${n[0]}">${icon(n[2])}<span>${n[1]}</span></button>`).join('')}</nav><div class="sidefoot"><div class="secure">${icon('shield')} พื้นที่ทำงานภายในคลินิก</div><small>Yuna Clinic Management · 1.0</small></div></aside><div class="workspace"><header class="topbar">${btn(icon('menu'),'menu','','mobile-menu')}<div class="breadcrumb">Workspace ${icon('chevron')} <b id="crumb">ภาพรวม</b></div><div class="topactions"><span class="today">${date(localDate())}</span>${btn(icon('bell'),'notifications','aria-label="การแจ้งเตือน"','quiet')}<div class="user"><span class="avatar">${esc(me.name.slice(0,1))}</span><div class="userinfo">${esc(me.name)}<small>${esc(me.role)}</small></div></div>${btn(icon('logout'),'logout','aria-label="ออกจากระบบ"','quiet')}</div></header><main class="content" id="content"></main></div>`;
}
async function loadView(v,keep=false){
 if(!me||!me.views.includes(v))return;view=v;if(!keep){tab='';page=1;query='';filter='';}const version=++routeVersion;
 $$('.navitem').forEach(n=>n.classList.toggle('active',n.dataset.view===v));$('.sidebar').classList.remove('open');$('#crumb').textContent=NAV.find(n=>n[0]===v)[1];
 try{const result=await api(v+(v==='dashboard'?'?month='+month:''));if(version!==routeVersion||!me)return;cache[v]=result;render();}catch(e){toast(e.message)}
}
function header(title,subtitle,action=''){return `<div class="pagehead"><div><div class="eyebrow">YUNA CLINIC / ${esc(view.toUpperCase())}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${action}</div></div>`}
function footer(){return '<footer class="footer"><span>© 2026 Yuna Clinic. All rights reserved.</span><span>CLINIC MANAGEMENT, THOUGHTFULLY DESIGNED.</span></footer>'}
function stat(label,value,note,i,cls=''){return `<div class="stat ${cls}"><div class="stat-top">${label}<span class="stat-icon">${icon(i)}</span></div><strong class="amount">${value}</strong><small>${note}</small></div>`}
function empty(title,sub='',action=''){return `<div class="empty">${icon(NAV.find(n=>n[0]===view)?.[2]||'file')}<h3>${title}</h3><p>${sub}</p>${action}</div>`}
function table(headers,rs,emptyText='ยังไม่มีรายการ'){return rs.length?`<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rs.map(r=>`<tr>${r.map(c=>`<td>${c??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty(emptyText)}
function person(p,showNickname=false){return `<div class="person"><span class="avatar">${esc(p.name?.slice(0,1)||'Y')}</span><div><b>${esc(p.name)}</b>${showNickname?`<small class="patient-nickname">ชื่อเล่น: ${esc(p.nickname?.trim()||'ยังไม่ระบุ')}</small>`:''}<small>${esc(p.hn?'HN '+p.hn:p.nickname||'')}</small></div></div>`}
function searchBox(placeholder='ค้นหา…'){return `<div class="search">${icon('search')}<input id="search" value="${esc(query)}" placeholder="${placeholder}" aria-label="${placeholder}"></div>`}
function tabs(items){if(!items.find(t=>t[0]===tab))tab=items[0][0];return `<div class="tabs">${items.map(t=>btn(t[1],'tab',`data-tab="${t[0]}"`,tab===t[0]?'active':'')).join('')}</div>`}
function paginate(arr,fn){const size=12,total=arr.length;page=Math.max(1,Math.min(page,Math.ceil(total/size)||1));return fn(arr.slice((page-1)*size,page*size))+`<div class="pagination"><span>${total?((page-1)*size+1)+'–'+Math.min(page*size,total):0} จาก ${count(total)} รายการ</span><div class="actions">${btn('‹','page','data-step="-1" '+(page===1?'disabled':''))}<span>${page} / ${Math.ceil(total/size)||1}</span>${btn('›','page','data-step="1" '+(page*size>=total?'disabled':''))}</div></div>`}
function matches(obj){return !query||Object.values(obj).some(v=>String(v??'').toLowerCase().includes(query.toLowerCase()))}
function render(){if(!me)return;const fn={dashboard:dashboard,patients:patients,appointments:appointments,procedures:procedures,packages:packages,inventory:inventory,finance:finance,fees:fees,users:users,audit:audit,privacy:privacy}[view];$('#content').innerHTML=fn()+footer()}
function chart(trend){
 const data=[...trend].reverse(),max=Math.max(1,...data.map(x=>x.amount))*1.15,w=620,h=180;
 const points=data.map((d,i)=>[45+i*(w-65)/Math.max(1,data.length-1),h-(d.amount/max)*(h-18)]);const path=points.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');
 return `<svg class="chart" role="img" aria-label="รายรับรายเดือนจากข้อมูลที่บันทึก" viewBox="0 0 640 210" preserveAspectRatio="none"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#c3a76a" stop-opacity=".19"/><stop offset="1" stop-color="#c3a76a" stop-opacity="0"/></linearGradient></defs>${[0,.25,.5,.75,1].map(x=>`<line class="chart-grid" x1="45" y1="${h-x*(h-18)}" x2="620" y2="${h-x*(h-18)}"/><text x="0" y="${h-x*(h-18)+4}">${Math.round(max*x/1000)}k</text>`).join('')}${points.length?`<path d="${path} L${points.at(-1)[0]},${h} L45,${h}Z" fill="url(#fade)"/><path d="${path}" fill="none" stroke="#b49757" stroke-width="2.5"/>${points.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="3.5" fill="#fff" stroke="#b49757" stroke-width="2"><title>${esc(data[i].month)}: ${money(data[i].amount)}</title></circle><text x="${p[0]}" y="205" text-anchor="middle">${new Date(data[i].month+'-01T12:00').toLocaleDateString('th-TH',{month:'short'})}</text>`).join('')}`:''}</svg>`;
}
function dashboard(){const d=cache.dashboard;const fin=!!d.totals;const rev=d.totals?.find(x=>x.kind==='receipt')||{},exp=d.totals?.find(x=>x.kind==='expense')||{};
 const newappt=me.views.includes('appointments')?btn(icon('plus')+' สร้างนัดหมาย','new-appointment','','primary'):'';
 let html=header('ภาพรวมคลินิก',`ยินดีต้อนรับ คุณ${esc(me.name)} · ดูแลทุกวันให้เป็นวันที่ดี`,(fin?`<input type="month" id="dashboard-month" aria-label="เดือนที่ต้องการดู" value="${month}">`:'')+newappt);
 html+=`<div class="stats">${fin?stat('รายรับเดือนนี้',money(rev.amount),`${count(rev.n)} รายการในเดือนที่เลือก`,'wallet','gold'):stat('บทบาทของคุณ',esc(me.role),'แสดงข้อมูลตามสิทธิ์การใช้งาน','shield','gold')}${d.patients!==null?stat('ผู้รับบริการทั้งหมด',count(d.patients),'เวชระเบียนที่มีอยู่ในระบบ','users'):stat('รายการรายรับ',count(rev.n),'ในเดือนที่เลือก','file')}${me.views.includes('appointments')?stat('นัดหมายวันนี้',count(d.appointments.length),'รวมทุกสถานะ • '+date(localDate()),'calendar'):stat('บทบาทการใช้งาน',esc(me.role),'แสดงข้อมูลที่ได้รับอนุญาต','shield')}${d.low!==null?stat('สินค้าใกล้หมด',count(d.low),'ยอดคงเหลือไม่เกินจุดแจ้งเตือน','box'):stat('รายจ่ายเดือนนี้',money(exp.amount),'รายการรายจ่ายที่บันทึก','coins')}</div>`;
 if(!fin&&!me.views.includes('appointments'))return html+`<section class="card"><div class="card-head"><h2>จัดการคลังสินค้า</h2></div><div class="card-body"><p class="muted">ตรวจสอบยอดคงเหลือ วันหมดอายุ และสินค้าที่ต้องรับเข้า</p><div class="actions" style="margin-top:20px">${btn(icon('box')+' เปิดคลังสินค้า','navigate','data-to="inventory"','primary')}${btn(icon('plus')+' รับสินค้า / ระบุ Lot','receive')}</div></div></section>`;
 if(fin){const max=Math.max(1,...d.categories.map(x=>x.amount));html+=`<div class="grid-main"><section class="card"><div class="card-head"><div><h2>แนวโน้มรายรับ</h2><p>8 เดือนล่าสุดที่มีข้อมูล</p></div><span class="legend"><i class="dot"></i> รายรับรวม</span></div><div class="card-body">${chart(d.trend)}<div class="chartfoot"><span>ยอดจากรายการรายรับและใบเสร็จ</span><span>หน่วย: บาท</span></div></div></section><section class="card"><div class="card-head"><div><h2>บริการยอดนิยม</h2><p>เรียงตามรายรับในเดือนที่เลือก</p></div>${icon('trend')}</div><div class="card-body"><div class="ranking">${d.categories.map((r,i)=>`<div><div class="rank-top"><span><small>0${i+1}</small> &nbsp;${esc(r.description)}</span><span>${money(r.amount)}</span></div><div class="rankbar"><i style="width:${r.amount/max*100}%"></i></div></div>`).join('')||empty('ยังไม่มีรายรับในเดือนนี้')}</div></div></section></div>`;}
 html+=`<div class="grid-main"><section class="card"><div class="card-head"><div><h2>${fin?'รายรับล่าสุด':'นัดหมายวันนี้'}</h2><p>${fin?'รายการล่าสุดที่บันทึกในคลินิก':'ผู้รับบริการที่มีนัดในวันนี้'}</p></div>${btn('ดูทั้งหมด '+icon('arrow'),'navigate',`data-to="${fin?'finance':'appointments'}"`,'quiet')}</div>${fin?table(['ผู้รับบริการ','บริการ','วันที่','รายรับ'],d.recent.map(r=>[person({name:r.customer}),esc(r.description),date(r.date),`<b>${money(r.amount)}</b>`])):queue(d.appointments)}</section><section class="card"><div class="card-head"><div><h2>${!me.views.includes('appointments')?'สรุปเดือนที่เลือก':fin?'นัดหมายวันนี้':'สิ่งที่ต้องดูแล'}</h2><p>${date(localDate())}</p></div>${pill(me.views.includes('appointments')?d.appointments.length+' นัด':month,'gold')}</div>${me.views.includes('appointments')?queue(d.appointments.slice(0,4)):`<div class="card-body"><p class="muted">รายจ่ายที่บันทึก</p><h2>${money(exp.amount)}</h2><p class="muted" style="margin-top:20px">กำไรตามต้นฉบับ</p><h2>${money(rev.profit)}</h2><p class="checknote">ยังไม่ใช่กำไรสุทธิหลังหักค่าใช้จ่ายทั้งหมด</p></div>`}</section></div>`;
 if(fin)html+=`<div class="notice">${icon('file')}<span>กำไรจากต้นฉบับในเดือนนี้ ${money(rev.profit)} · ตัวเลขนี้มาจากคอลัมน์ “กำไร” ในไฟล์ และยังไม่ใช่กำไรสุทธิหลังหักค่าใช้จ่ายทั้งหมด</span></div>`;
 return html;
}
function queue(arr){return arr.length?arr.map(a=>`<div class="queue"><time>${esc(a.start.slice(11,16))}</time><div class="queue-main"><b>${esc(a.name)}</b><small>${esc(a.service)} · ${esc(a.room)}</small></div>${status(a.status)}</div>`).join(''):empty('ยังไม่มีนัดหมายวันนี้','สร้างนัดหมายเพื่อจัดคิวแพทย์และห้องหัตถการ',me.views.includes('appointments')?btn(icon('plus')+' สร้างนัดหมาย','new-appointment'):'' )}
function patients(){let a=cache.patients.filter(matches);return header('ผู้รับบริการ & เวชระเบียน',`${count(cache.patients.length)} ราย · ประวัติการดูแลในที่เดียว`,btn(icon('plus')+' เพิ่มผู้รับบริการ','new-patient','','primary'))+`<div class="toolbar">${searchBox('ค้นหาชื่อ ชื่อเล่น เบอร์โทร หรือ HN')}<span class="muted" style="font-size:13px">${me.role==='Front'?'มุมมองข้อมูลติดต่อและสมาชิก':'ประวัติ • Consent • ภาพก่อน–หลัง'}</span></div><section class="card">${paginate(a,rs=>table(['ผู้รับบริการ','อายุ','เบอร์โทร','สมาชิก',...(me.role==='Front'?[]:['ประวัติแพ้ยา']), ''],rs.map(p=>[person(p,true),p.age?esc(p.age)+' ปี':'—',esc(p.phone)||'—',pill(p.member,p.member==='Gold'?'gold':''),...(me.role==='Front'?[]:[p.allergies?pill(p.allergies,p.allergies==='ไม่มี'?'green':'red'):pill('ยังไม่ระบุ')]),btn('ดูประวัติ '+icon('chevron'),'patient',`data-id="${p.id}"`,'quiet')])) )}</section>`}
function appointments(){const d=cache.appointments;let html=header('นัดหมาย & คิวแพทย์','จัดเวลาแพทย์ ห้องหัตถการ และติดตามหลังทำ',btn(icon('plus')+' สร้างนัดหมาย','new-appointment','','primary'))+tabs([['all','นัดหมายทั้งหมด'],['today','คิววันนี้'],['followup','ติดตามหลังทำ']]);let arr=d.filter(matches).filter(a=>tab==='today'?a.start.slice(0,10)===localDate():tab==='followup'?a.followup&&a.status!=='ยกเลิก':true).filter(a=>!filter||a.start.slice(0,10)===filter);html+=`<div class="toolbar">${searchBox('ค้นหาผู้รับบริการ แพทย์ ห้อง หรือบริการ')}<input type="date" id="date-filter" aria-label="กรองวันนัดหมาย" value="${filter}">${filter?btn('ล้างวันที่','clear-filter'):''}</div><section class="card">`;
 html+=paginate(arr,rs=>tab==='followup'?table(['ผู้รับบริการ','บริการ','วันติดตาม','ผลติดตาม',''],rs.map(a=>[person(a),esc(a.service),date(a.followup),a.followup_note?esc(a.followup_note):pill('รอติดตาม','gold'),btn('บันทึกผล','followup',`data-id="${a.id}"`)]),'ยังไม่มีนัดติดตาม'):table(['วัน / เวลา','ผู้รับบริการ','บริการ','แพทย์ / ห้อง','สถานะ',''],rs.map(a=>[`<b>${esc(a.start.slice(11,16))}</b><small>${date(a.start)}</small>`,person(a),esc(a.service)+`<small>${a.duration} นาที</small>`,esc(a.doctor)+`<small>${esc(a.room)}</small>`,status(a.status),btn('จัดการคิว','appointment-status',`data-id="${a.id}"`)]),'ยังไม่มีนัดหมาย'))+'</section>';return html;}
function procedures(){const d=cache.procedures.filter(matches);return header('บันทึกหัตถการ','ตรวจสอบประวัติ เชื่อม Lot และบันทึกผู้ให้บริการ',btn(icon('plus')+' บันทึกหัตถการ','new-procedure','','primary'))+`<div class="toolbar">${searchBox('ค้นหาผู้รับบริการ หัตถการ หรือแพทย์')}</div><section class="card">${paginate(d,rs=>table(['วันที่','ผู้รับบริการ','หัตถการ','ผู้ให้บริการ','Lot ที่ใช้',''],rs.map(r=>[date(r.created),person(r),esc(r.service),esc(r.doctor)+`<small>${esc(r.nurse)}</small>`,r.lots.map(l=>`${esc(l.name)} · ${esc(l.lot)} × ${l.qty}`).join('<br>')||'ไม่มีผลิตภัณฑ์ที่เบิก',btn('รายละเอียด','procedure-detail',`data-id="${r.id}"`)]),'ยังไม่มีการบันทึกหัตถการ'))}</section>`}
function packages(){const d=cache.packages;let html=header('คอร์ส แพ็กเกจ & สมาชิก','ติดตามยอดใช้บริการและสิทธิประโยชน์',btn(icon('plus')+' เพิ่มคอร์ส','new-package','','primary'))+tabs([['courses','คอร์สของผู้รับบริการ'],['promos','โปรโมชั่น'],['history','ประวัติใช้คอร์ส']])+`<div class="toolbar">${searchBox('ค้นหาชื่อผู้รับบริการหรือคอร์ส')}${tab==='promos'?btn(icon('plus')+' เพิ่มโปรโมชั่น','new-promo'):''}</div>`;
 if(tab==='courses'){const arr=d.packages.filter(matches);html+=arr.length?`<div class="cards">${arr.map(k=>`<article class="package"><div class="tag">YUNA TREATMENT COURSE</div><h2>${esc(k.name)}</h2><p class="muted">${esc(k.patient)}</p><div class="balance">${k.remaining}<span> / ${k.total} ครั้งคงเหลือ</span></div><div class="progress"><i style="width:${k.remaining/k.total*100}%"></i></div><p style="margin-top:18px"><small>หมดอายุ ${date(k.expiry)} · ${money(k.price)}</small></p>${k.expiry<localDate()?pill('หมดอายุ','red'):k.remaining===0?pill('ใช้ครบแล้ว'):btn('ใช้สิทธิ์คอร์ส '+icon('arrow'),'redeem',`data-id="${k.id}"`)}</article>`).join('')}</div>`:`<section class="card">${empty('ยังไม่มีคอร์ส','เพิ่มคอร์สที่ผู้รับบริการซื้อแล้ว เพื่อบันทึกจำนวนครั้งและยอดคงเหลือ')}</section>`;}
 if(tab==='promos')html+=`<section class="card">${table(['โปรโมชั่น','ส่วนลด','ช่วงเวลา','เงื่อนไข','สถานะ'],d.promotions.filter(matches).map(p=>[esc(p.name),p.discount+'%',date(p.start)+' – '+date(p.end),esc(p.terms),pill(p.start>localDate()?'ยังไม่เริ่ม':p.end<localDate()?'สิ้นสุดแล้ว':'ใช้งานอยู่',p.start<=localDate()&&p.end>=localDate()?'green':'')]))}</section>`;
 if(tab==='history')html+=`<section class="card">${paginate(d.redemptions.filter(matches),rs=>table(['วันที่','ผู้รับบริการ','คอร์ส','จำนวนครั้ง','หมายเหตุ'],rs.map(r=>[date(r.created),esc(r.patient),esc(r.package),r.qty,esc(r.reason)])))}</section>`;return html;}
function inventory(){const d=cache.inventory;const editable=['Owner','คลัง'].includes(me.role);const warning=d.products.filter(p=>p.opening!==0).length;let html=header('คลังสินค้า','จัดการ Lot วันหมดอายุ และการเบิกแบบ FEFO',editable?btn(icon('plus')+' รับสินค้า / ระบุ Lot','receive','','primary'):'');html+=`<div class="stats">${stat('รายการสินค้า',count(d.products.length),'ประเภทสินค้าในคลัง','box','gold')}${stat('สินค้าใกล้หมด',count(d.products.filter(p=>p.stock<=p.min_stock).length),'คงเหลือไม่เกินจุดแจ้งเตือน','bell')}${stat('ใกล้หมดอายุ',count(d.lots.filter(l=>l.qty>0&&l.expiry>=localDate()&&(new Date(l.expiry)-new Date(localDate()))/864e5<=90).length),'Lot ที่หมดอายุภายใน 90 วัน','clock')}${stat('รอระบุ Lot',count(warning),'รายการที่มียอดตั้งต้นคงค้าง','file')}</div>`;
 html+=tabs([['products','สินค้าทั้งหมด'],['lots','Lot / FEFO'],['movements','ความเคลื่อนไหว'],['legacy','ประวัติจากไฟล์']])+`<div class="toolbar">${searchBox('ค้นหาสินค้า รหัส หรือ Lot')}${editable&&tab==='products'?btn(icon('plus')+' เพิ่มสินค้า','new-product'):''}</div>`;
 if(tab==='products'){html+=`<div class="notice">${icon('shield')}ยอดตั้งต้น ${count(warning)} รายการยังไม่ทราบ Lot/วันหมดอายุ ต้องจัดสรรยอดตั้งต้นเข้า Lot ก่อนเบิกหัตถการ โดยไม่เพิ่มยอดซ้ำ${d.products.some(p=>p.opening<0)?' · มีข้อมูลยอดตั้งต้นติดลบ กรุณาตรวจนับและแก้พร้อมระบุเหตุผล':''}</div><section class="card">${paginate(d.products.filter(matches),rs=>table(['สินค้า','หมวดหมู่','คงเหลือรวม','ยังไม่ระบุ Lot','จุดแจ้งเตือน','สถานะ',...(editable?['']:[])],rs.map(p=>[`<b>${esc(p.name)}</b>${showNickname?`<small class="patient-nickname">ชื่อเล่น: ${esc(p.nickname?.trim()||'ยังไม่ระบุ')}</small>`:''}<small>${esc(p.code)}</small>`,esc(p.category),`${count(p.stock)} ${esc(p.unit)}`,count(p.opening),count(p.min_stock),p.opening<0?pill('ยอดตั้งต้นติดลบ','red'):p.stock<=p.min_stock?pill('ใกล้หมด','red'):p.opening===p.stock?pill('รอระบุ Lot','gold'):pill('มีสินค้า','green'),...(editable?[btn('แก้ยอดตั้งต้น','opening-stock',`data-id="${p.id}"`)]:[])])) )}</section>`;}
 if(tab==='lots')html+=`<div class="notice">${icon('clock')}เบิกอัตโนมัติจาก Lot ที่หมดอายุก่อน และข้ามสินค้าที่หมดอายุแล้ว</div><section class="card">${paginate(d.lots.filter(matches),rs=>table(['สินค้า','Lot','วันหมดอายุ','จำนวน','สถานะ',...(editable?['']:[])],rs.map(l=>[esc(l.name),esc(l.lot),date(l.expiry),`${count(l.qty)} ${esc(l.unit)}`,l.expiry<localDate()?pill('หมดอายุ','red'):pill('ใช้ได้','green'),...(editable?[btn('ปรับออก','adjust-lot',`data-id="${l.id}"`)]:[])])))}</section>`;
 if(tab==='movements')html+=`<section class="card">${paginate(d.movements.filter(matches),rs=>table(['วันที่','สินค้า','Lot','จำนวนเปลี่ยนแปลง','เหตุผล'],rs.map(m=>[date(m.created),esc(m.name),esc(m.lot),pill((m.qty>0?'+':'')+m.qty,m.qty>0?'green':'gold'),esc(m.reason)])))}</section>`;
 if(tab==='legacy')html+=`<div class="notice">${icon('file')}100 รายการล่าสุดจากไฟล์ต้นฉบับ · เก็บเป็นประวัติอ้างอิง ไม่ตัดซ้ำจากยอด inventory และไม่ใช้คอลัมน์ Unit price เป็นราคาต้นทุนเพราะข้อมูลในช่องเป็นหน่วยสินค้า</div><section class="card">${paginate(d.legacy.filter(matches),rs=>table(['วันที่','สินค้า','ทิศทาง','จำนวน','หน่วย','แถวต้นฉบับ'],rs.map(m=>[date(m.date),esc(m.name),pill(m.direction==='in'?'รับเข้า':'เบิกออก',m.direction==='in'?'green':'gold'),m.qty,esc(m.unit),m.source_row])))}</section>`;return html;}
function finance(){const d=cache.finance;const owner=me.role!=='Front';let html=header('การเงิน & เอกสาร','ใบเสนอราคา ใบเสร็จ และรายการรับ–จ่าย',btn(icon('plus')+' สร้างเอกสาร','new-finance','','primary'));html+=tabs([['receipt','รายรับ / ใบเสร็จ'],['quote','ใบเสนอราคา'],...(owner?[['expense','รายจ่าย'],['summary','สรุปกำไร']]:[])]);
 if(tab==='summary'){const income=d.filter(x=>x.kind==='receipt'&&x.date.startsWith(month)),expense=d.filter(x=>x.kind==='expense'&&x.date.startsWith(month)).reduce((s,x)=>s+x.amount,0),rev=income.reduce((s,x)=>s+x.amount,0),profit=income.reduce((s,x)=>s+(x.source_profit||0),0);return html+`<div class="toolbar"><input type="month" id="finance-month" aria-label="เดือนสรุป" value="${month}"></div><div class="stats">${stat('รายรับ',money(rev),'เดือนที่เลือก','wallet','gold')}${stat('รายจ่ายที่บันทึก',money(expense),'ยังไม่รวมค่ามือ/คอมฯ ถ้าไม่ได้ลงรายจ่าย','coins')}${stat('ส่วนต่างรับ–จ่าย',money(rev-expense),'ยังไม่ใช่กำไรสุทธิทางบัญชี','trend')}${stat('กำไรตามต้นฉบับ',money(profit),'รวมเฉพาะแถวที่มีข้อมูลกำไร','file')}</div><div class="notice">${icon('file')}ยังสรุปกำไรสุทธิไม่ได้อัตโนมัติ: ไฟล์ไม่มีต้นทุนครบทุก Lot และค่าใช้จ่ายทั้งหมด รายการใหม่จะไม่ถูกเติมกำไรเป็นศูนย์ ต้องกระทบยอดต้นทุน ค่ามือ และค่าคอมมิชชันก่อนใช้เป็นรายงานบัญชี</div>`;}
 const a=d.filter(x=>x.kind===tab).filter(matches).filter(x=>!filter||x.date.startsWith(filter));html+=`<div class="toolbar">${searchBox('ค้นหาผู้รับบริการ รายการ หรือเลขเอกสาร')}<input type="month" id="month-filter" aria-label="กรองเดือน" value="${filter}">${btn(icon('download')+' ส่งออก CSV','export-finance')}</div><section class="card">${paginate(a,rs=>table(['เลขที่ / วันที่','ผู้รับบริการ / ผู้รับเงิน','รายการ','ยอดเงิน',''],rs.map(r=>[`<b>${docno(r)}</b><small>${date(r.date)}</small>`,esc(r.customer),esc(r.description),`<b>${money(r.amount)}</b>`,btn(icon('file'),'print',`data-id="${r.id}" aria-label="พิมพ์เอกสาร"`,'quiet')+(r.kind==='quote'?(d.some(x=>x.quote_id===r.id)?pill('ออกใบเสร็จแล้ว','green'):btn('รับชำระ / ออกใบเสร็จ','convert',`data-id="${r.id}"`)):'')])) )}</section>`;return html;}
function docno(r){return (r.kind==='quote'?'QT':r.kind==='expense'?'EX':'RC')+'-'+String(r.id).padStart(6,'0')}
function fees(){const d=cache.fees.filter(x=>x.created.startsWith(month));const groups=new Map();d.forEach(r=>{for(const [name,kind,amount] of [[r.doctor,'ค่ามือแพทย์',r.doctor_fee],[r.staff,'ค่าคอมมิชชัน',r.commission]]){if(!name)continue;const k=name+kind;if(!groups.has(k))groups.set(k,{name,kind,amount:0,n:0});groups.get(k).amount+=amount;groups.get(k).n++}});return header('ค่ามือ & คอมมิชชัน','สรุปจากยอดที่บันทึกจริงในแต่ละหัตถการ',`<input type="month" id="fees-month" aria-label="เดือนค่าตอบแทน" value="${month}">`)+`<div class="stats">${stat('ค่ามือแพทย์',money(d.reduce((s,r)=>s+r.doctor_fee,0)),'ตามรายการหัตถการ','coins','gold')}${stat('คอมมิชชันพนักงาน',money(d.reduce((s,r)=>s+r.commission,0)),'ตามรายการหัตถการ','users')}${stat('หัตถการ',count(d.length),'เดือนที่เลือก','heart')}</div><div class="notice">${icon('file')}รายงานยอดค้างจ่ายอ้างอิงจากการบันทึกหัตถการ ยังไม่ใช่หลักฐานการจ่ายเงิน กรุณาบันทึกรายจ่ายเมื่อชำระจริง</div><section class="card">${table(['ผู้รับค่าตอบแทน','ประเภท','จำนวนรายการ','ยอดรวม'],[...groups.values()].map(g=>[esc(g.name),g.kind,g.n,money(g.amount)]))}</section>`;}
function users(){const d=cache.users;return header('ผู้ใช้งาน & สิทธิ์','กำหนดบทบาทและจัดการการเข้าถึงของทีม',btn(icon('plus')+' เพิ่มผู้ใช้งาน','new-user','','primary'))+`<section class="card">${table(['ผู้ใช้งาน','ชื่อผู้ใช้','บทบาท','สถานะ',''],d.map(u=>[person(u),esc(u.username),pill(u.role,'gold'),pill(u.active?'ใช้งานอยู่':'ปิดใช้งาน',u.active?'green':'red'),btn('ตั้งรหัสผ่านใหม่','reset-password',`data-id="${u.id}"`)+(u.id!==me.id?btn(u.active?'ปิดบัญชี':'เปิดบัญชี','toggle-user',`data-id="${u.id}"`,'quiet'): '')]))}</section><div style="margin-top:24px" class="card"><div class="card-head"><h2>สิทธิ์ตามบทบาท</h2></div>${table(['บทบาท','ขอบเขตการใช้งาน'],[['Owner','ทุกส่วน รวมจัดการผู้ใช้และประวัติการใช้งาน'],['แพทย์','เวชระเบียน Consent ภาพ หัตถการ นัดหมาย และดูคลัง'],['พยาบาล','เวชระเบียน Consent ภาพ หัตถการ นัดหมาย และดูคลัง'],['Front','ข้อมูลติดต่อผู้รับบริการ นัดหมาย คอร์ส สมาชิก ใบเสนอราคาและใบเสร็จ'],['คลัง','สินค้า Lot รับเข้า และปรับยอดออก'],['บัญชี','รายรับ รายจ่าย สรุปการเงิน และค่าตอบแทน']])}</div>`;}
function audit(){return header('ประวัติการใช้งาน','บันทึกการเข้าสู่ระบบ เปิดเวชระเบียน และเปลี่ยนแปลงข้อมูล')+`<div class="toolbar">${searchBox('ค้นหาผู้ใช้งาน กิจกรรม หรือรายการ')}</div><section class="card">${paginate(cache.audit.filter(matches),rs=>table(['เวลา','ผู้ใช้งาน','กิจกรรม','ส่วนงาน','อ้างอิง','รายละเอียด'],rs.map(r=>[esc(r.created.replace('T',' ')),esc(r.actor),r.action==='opening'?'แก้ยอดตั้งต้น':esc(actionName(r.action)),esc(NAV.find(n=>n[0]===r.entity)?.[1]||r.entity),esc(r.entity_id)||'—',esc(r.detail)||'—'])))}</section><p class="checknote">แสดง 500 กิจกรรมล่าสุด · ไม่มีคำสั่งแก้ไขหรือลบ Audit log ผ่านหน้าเว็บ</p>`;}
function actionName(s){return ({create:'เพิ่มรายการ',review:'ทบทวนเวชระเบียน',consent:'บันทึกความยินยอม',photo:'เพิ่มภาพ',receive:'รับสินค้า / จัดสรร Lot',adjust:'ปรับสินค้าออก',status:'เปลี่ยนสถานะ',followup:'ติดตามผล',redeem:'ใช้สิทธิ์คอร์ส',promotion:'เพิ่มโปรโมชั่น',convert:'ออกใบเสร็จจากใบเสนอราคา',toggle:'เปลี่ยนสถานะบัญชี',password:'ตั้งรหัสผ่านใหม่',member:'เปลี่ยนระดับสมาชิก',product:'เพิ่มสินค้า'})[s]||s}
function privacy(){const d=cache.privacy;return header('ความเป็นส่วนตัว & PDPA','เครื่องมือช่วยจัดการข้อมูลและความยินยอมของผู้รับบริการ')+`<div class="policygrid"><section class="card">${icon('shield')}<h2>สิทธิ์เข้าถึงตามบทบาท</h2><p>ตรวจสิทธิ์ที่ระบบหลังบ้านทุกคำขอ Front ดูข้อมูลติดต่อและสมาชิกได้ แต่ไม่เห็นประวัติแพ้ยา โรคประจำตัว หรือภาพ</p></section><section class="card">${icon('lock')}<h2>การเข้าสู่ระบบ</h2><p>เก็บรหัสผ่านด้วย PBKDF2 ตรวจ CSRF และหมดอายุการเข้าใช้เมื่อไม่มีคำขอ 30 นาที หรือครบ 8 ชั่วโมง</p></section><section class="card">${icon('camera')}<h2>Consent และภาพการรักษา</h2><p>แยกความยินยอมการรักษาและภาพก่อน–หลัง เก็บเวอร์ชันและผู้ลงนาม พร้อมประวัติถอนความยินยอม รูปภาพต้องเข้าสู่ระบบก่อนดู</p></section><section class="card">${icon('clock')}<h2>ตรวจสอบย้อนหลัง</h2><p>บันทึกผู้ใช้งาน เวลา และรายการที่เปลี่ยนแปลง รวมการเปิดเวชระเบียนและภาพ โดยไม่คัดลอกข้อมูลสุขภาพลงในบันทึกกิจกรรม</p></section></div><div class="notice" style="margin-top:22px">${icon('file')}เครื่องมือเหล่านี้ยังไม่ใช่การรับรอง PDPA คลินิกต้องกำหนดประกาศความเป็นส่วนตัว ระยะเวลาเก็บข้อมูล ช่องทางขอใช้สิทธิ์ การสำรอง/ลบข้อมูล และผู้รับผิดชอบก่อนใช้จริง</div><section class="card"><div class="card-head"><h2>ประวัติความยินยอม</h2></div>${table(['ผู้รับบริการ','วัตถุประสงค์','สถานะ','เวอร์ชัน','วันที่'],d.consents.map(c=>[esc(c.name),esc(c.purpose),status(c.decision),esc(c.version),date(c.created)]))}</section><section class="card" style="margin-top:22px"><div class="card-head"><h2>ข้อมูลที่นำเข้า</h2>${pill(d.source.source||'ไม่มีไฟล์','gold')}</div><div class="card-body"><p style="font-size:14px">${(d.source.notes||[]).map(n=>'• '+esc(n)).join('<br>')}</p></div></section>`;}

function field(name,label,type='text',value='',attrs={}){const attr=Object.entries(attrs).map(([k,v])=>`${k}="${esc(v)}"`).join(' ');return `<div class="field ${type==='textarea'?'full':''}"><label for="f-${name}">${label}</label>${type==='textarea'?`<textarea id="f-${name}" name="${name}" ${attr}>${esc(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attr} ${attrs.optional?'':'required'}>`}</div>`}
function select(name,label,options,value=''){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" required>${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`}).join('')}</select></div>`}
function modal(title,body){const el=$('#modal');el.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2>${btn(icon('close'),'close','aria-label="ปิด"','quiet')}</div><div class="modal-body">${body}</div>`;if(!el.open)el.showModal();$('.modal-body',el).scrollTop=0;}
function form(title,body,onSubmit,label='บันทึกข้อมูล'){
 formHandler=onSubmit;modal(title,`<form id="modal-form"><div class="formgrid">${body}</div><div id="form-error" class="error" role="alert"></div><div class="form-actions">${btn('ยกเลิก','close')}<button class="primary" type="submit">${label}</button></div></form>`);
 $$('#modal-form button[data-act]').forEach(b=>b.type='button');
 $('#modal-form').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);b.disabled=true;const data=Object.fromEntries(new FormData(e.target));try{await formHandler(data,e.target);$('#modal').close();toast('บันทึกข้อมูลเรียบร้อย');await loadView(view,true)}catch(err){$('#form-error').textContent=err.message;b.disabled=false}};
}
async function pickPatients(){const ps=await api('patients');return [['','เลือกผู้รับบริการ'],...ps.map(p=>[p.id,p.hn+' · '+p.name])];}
async function patientDetail(id){const p=await api('patients?id='+id);currentPatient=p;let body=`<div class="actions" style="margin-bottom:20px">${pill('HN '+p.hn,'gold')}${pill(p.member)}<span class="muted">ชื่อเล่น: ${esc(p.nickname?.trim()||'ยังไม่ระบุ')}</span></div><div class="detailgrid">${[['ชื่อ–นามสกุล',p.name],['อายุ',p.age?p.age+' ปี':'ยังไม่ระบุ'],['โทรศัพท์',p.phone||'ยังไม่ระบุ'],['สมาชิก',p.member]].map(([k,v])=>`<div class="detailitem"><small>${k}</small><p>${esc(v)}</p></div>`).join('')}</div>${['Owner','Front'].includes(me.role)?btn('เปลี่ยนระดับสมาชิก','member',`data-id="${p.id}"`):''}`;
 if(me.role!=='Front'){body+=`<div class="detailsection"><h3>ประวัติสุขภาพ</h3>${btn('ทบทวน / แก้ไข','clinical-review',`data-id="${p.id}"`)}</div>${p.clinical_review?pill('ทบทวนแล้ว','green'):`<div class="notice">${icon('bell')}ยังไม่ผ่านการทบทวนประวัติก่อนทำหัตถการ</div>`}<div class="detailgrid" style="margin-top:14px">${[['แพ้ยา',p.allergies],['โรคประจำตัว',p.conditions],['ยาที่รับประทาน',p.medicines],['ผู้ติดต่อฉุกเฉิน',p.emergency],['ที่อยู่',p.address]].map(([k,v])=>`<div class="detailitem"><small>${k}</small><p>${esc(v)||'ยังไม่ระบุ'}</p></div>`).join('')}</div><div class="detailsection"><h3>Consent</h3>${btn(icon('plus')+' บันทึก','consent',`data-id="${p.id}"`)}</div>${table(['วัตถุประสงค์','สถานะ','ผู้ลงนาม','เวอร์ชัน'],p.consents.map(c=>[esc(c.purpose),status(c.decision),esc(c.signed_by),esc(c.version)]))}<div class="detailsection"><h3>ภาพก่อน–หลัง</h3>${btn(icon('camera')+' เพิ่มภาพ','photo',`data-id="${p.id}"`)}</div><div class="photo-grid">${p.photos.map(ph=>`<figure><img src="/api/procedures/photo?id=${ph.id}" alt="${esc(ph.phase)}" loading="lazy"><figcaption>${esc(ph.phase)} · ${date(ph.created)}<br>${esc(ph.note)}</figcaption></figure>`).join('')}</div>${p.photos.length?'':empty('ยังไม่มีภาพ','บันทึกความยินยอมก่อนอัปโหลดภาพ')}<div class="detailsection"><h3>ประวัติหัตถการ</h3></div>${table(['วันที่','หัตถการ','แพทย์'],p.procedures.map(t=>[date(t.created),esc(t.service),esc(t.doctor)]))}`;}
 modal(esc(p.name),body);
}
async function newAppointment(){const opts=await pickPatients();form('สร้างนัดหมาย',select('patient_id','ผู้รับบริการ',opts)+field('service','บริการ / หัตถการ')+field('doctor','แพทย์')+select('room','ห้องหัตถการ',['ห้อง 1','ห้อง 2','ห้อง 3','ห้องปรึกษา'])+field('start','วันและเวลา','datetime-local',localDate()+'T10:00')+field('duration','ระยะเวลา (นาที)','number',30,{min:1,max:480})+field('followup','วันที่ติดตามหลังทำ','date','',{optional:true}),d=>api('appointments',d))}
async function newProcedure(){const patients=await api('patients'),stock=await api('inventory');let ps=null;
 const patientLabel=p=>p.hn+' · '+p.name+(p.nickname?' · ชื่อเล่น: '+p.nickname:'');
 const opts=[['','เลือกผู้รับบริการ'],...patients.map(p=>[p.id,patientLabel(p)])];
 const productOptions=[['','ไม่เบิกสินค้า'],...stock.products.map(p=>[p.id,p.name+' ('+p.unit+')'])];
 form('บันทึกหัตถการ','<div class="field full"><label for="procedure-patient-search">ค้นหาผู้รับบริการ</label><input id="procedure-patient-search" type="search" placeholder="พิมพ์ชื่อ ชื่อเล่น เบอร์โทร หรือ HN" autocomplete="off" aria-controls="f-patient_id" aria-describedby="procedure-patient-results"><small id="procedure-patient-results" role="status" aria-live="polite">พิมพ์เพื่อกรองรายการ แล้วเลือกผู้รับบริการด้านล่าง</small></div>'+select('patient_id','ผู้รับบริการ',opts)+field('service','ชื่อหัตถการ')+'<div class="full field"><div id="clinical-warning" class="notice">เลือกผู้รับบริการเพื่อแสดงประวัติแพ้ยาและโรคประจำตัว</div></div>'+field('doctor','แพทย์ผู้ให้บริการ','text',me.role==='แพทย์'?me.name:'')+field('nurse','พยาบาล / ผู้ช่วย','text',me.role==='พยาบาล'?me.name:'',{optional:true})+field('note','รายละเอียดหัตถการ / ตำแหน่ง / ปริมาณ / ข้อสังเกต','textarea','',{required:'required'})+`<div class="field full"><label>ยา / ผลิตภัณฑ์ที่ใช้ (ตัด Lot ตาม FEFO)</label><div id="procedure-items"></div>${btn(icon('plus')+' เพิ่มผลิตภัณฑ์','add-item')}</div>`+field('doctor_fee','ค่ามือแพทย์ (บาท)','number',0,{min:0,step:'.01'})+field('staff','พนักงานรับคอมมิชชัน','text','',{optional:true})+field('commission','ค่าคอมมิชชัน (บาท)','number',0,{min:0,step:'.01'})+`<label class="checkrow field full"><input type="checkbox" name="review_confirmed" required>ยืนยันทบทวนประวัติแพ้ยา โรคประจำตัว และความเหมาะสมของหัตถการแล้ว</label>`,async(d,f)=>{d.review_confirmed=f.review_confirmed.checked;d.items=$$('.inline-items',f).map(row=>({product_id:$('select',row).value,qty:$('input',row).value})).filter(x=>x.product_id);return api('procedures',d)});
 cache.itemOptions=productOptions;addItem();$('#f-patient_id').onchange=async e=>{const el=$('#clinical-warning');const selected=e.target.value;el.classList.remove('red');el.textContent=selected?'กำลังโหลดประวัติผู้รับบริการ…':'เลือกผู้รับบริการเพื่อแสดงประวัติแพ้ยาและโรคประจำตัว';if(!selected)return;try{ps=await api('patients?id='+selected);if(!el.isConnected||$('#f-patient_id')?.value!==selected)return;el.innerHTML=`<span>แพ้ยา: <b>${esc(ps.allergies)||'ยังไม่ระบุ'}</b><br>โรคประจำตัว: ${esc(ps.conditions)||'ยังไม่ระบุ'}<br>${ps.clinical_review?'ทบทวนประวัติแล้ว':'ยังต้องทบทวนเวชระเบียน'} · Consent การรักษา: ${esc(ps.consents.find(c=>c.purpose==='การรักษา')?.decision||'ยังไม่มี')}</span>`;el.classList.toggle('red',!!ps.allergies&&ps.allergies!=='ไม่มี')}catch(err){toast(err.message)}};
 $('#procedure-patient-search').oninput=e=>{const term=e.target.value.trim().toLocaleLowerCase();const matches=patients.filter(p=>[p.hn,p.name,p.nickname,p.phone].some(v=>String(v??'').toLocaleLowerCase().includes(term)));const picker=$('#f-patient_id'),previous=picker.value;picker.innerHTML='<option value="">'+(matches.length?'เลือกผู้รับบริการ':'ไม่พบผู้รับบริการ')+'</option>'+matches.map(p=>`<option value="${esc(p.id)}">${esc(patientLabel(p))}</option>`).join('');picker.value=matches.some(p=>String(p.id)===previous)?previous:'';$('#procedure-patient-results').textContent=matches.length?'พบ '+matches.length+' ราย · เลือกผู้รับบริการด้านล่าง':'ไม่พบผู้รับบริการ ลองเปลี่ยนคำค้นหา';if(picker.value!==previous)picker.dispatchEvent(new Event('change'));};
}
function addItem(){const el=$('#procedure-items');if(!el)return;const row=document.createElement('div');row.className='inline-items';row.innerHTML=`<select aria-label="ผลิตภัณฑ์">${cache.itemOptions.map(([v,l])=>`<option value="${esc(v)}">${esc(l)}</option>`).join('')}</select><input type="number" min="0.001" step="any" value="1" aria-label="จำนวน" required>${btn(icon('close'),'remove-item','type="button" aria-label="ลบรายการ"')}`;el.append(row)}
async function receive(){const d=cache.inventory||await api('inventory');form('รับสินค้า / ระบุ Lot',select('product_id','สินค้า',[['','เลือกสินค้า'],...d.products.map(p=>[p.id,`${p.name} · รอระบุ Lot ${p.opening} ${p.unit}`])])+field('lot','เลข Lot')+field('expiry','วันหมดอายุ','date','',{min:localDate()})+field('qty','จำนวน','number',1,{min:0.001,step:'any'})+field('cost','ต้นทุนต่อหน่วย (บาท)','number',0,{min:0,step:'.01'})+`<label class="checkrow field full"><input type="checkbox" name="reconcile" checked>จัดสรรจากยอดตั้งต้นในไฟล์ (ไม่เพิ่มยอดคงเหลือรวม) — เอาเครื่องหมายออกเมื่อเป็นสินค้ารับเข้าใหม่</label>`,(d,f)=>api('inventory/receive',{...d,reconcile:f.reconcile.checked}))}
async function newFinance(){const ps=[['','เลือกผู้รับบริการ'],...(await api('finance/patients')).map(p=>[p.id,p.hn+' · '+p.name])];form('สร้างเอกสารการเงิน',select('kind','ประเภทเอกสาร',[['receipt','ใบเสร็จ / รายรับ'],['quote','ใบเสนอราคา'],...(me.role!=='Front'?[['expense','รายจ่าย']]:[])])+field('date','วันที่','date',localDate())+select('patient_id','ผู้รับบริการ (หรือระบุชื่อด้านข้าง)',[['','ไม่เชื่อมเวชระเบียน'],...ps.slice(1)])+field('customer','ชื่อลูกค้า / ผู้รับเงิน','text','',{optional:true})+field('description','รายการ / รายละเอียด','textarea','',{required:'required'})+field('amount','ยอดสุทธิ (บาท)','number','',{min:'.01',step:'.01'})+'<p class="field full checknote">กรอกยอดสุทธิหลังส่วนลดและภาษีที่เกี่ยวข้อง เอกสารนี้ไม่ใช่ใบกำกับภาษี</p>',d=>api('finance',d));$('#f-patient_id').required=false;}
function downloadCSV(rs,headers,filename){const cell=v=>'"'+String(v??'').replace(/^[=+\-@\t\r]/,"'$&").replace(/"/g,'""')+'"';const text='\uFEFF'+[headers,...rs].map(r=>r.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function printDoc(r){$('#print').innerHTML=`<h1>YUNA CLINIC</h1><p>${r.kind==='quote'?'ใบเสนอราคา':r.kind==='expense'?'บันทึกรายจ่าย':'ใบเสร็จรับเงิน'}</p><p>เลขที่ ${docno(r)} · วันที่ ${date(r.date)}</p><p>${r.kind==='expense'?'ผู้รับเงิน':'ผู้รับบริการ'}: ${esc(r.customer)}</p>${table(['รายการ','จำนวนเงิน'],[[esc(r.description),money(r.amount)]])}<div class="total">รวมสุทธิ ${money(r.amount)}</div><p style="margin-top:60px">ลงชื่อผู้รับเงิน / ผู้จัดทำ __________________________</p><p><small>เอกสารภายในคลินิก ไม่ใช่ใบกำกับภาษี${r.source?.startsWith('sample')?' · สร้างจากประวัติรายรับที่นำเข้า ไม่ใช่สำเนาใบเสร็จต้นฉบับ':''}</small></p>`;window.print()}

document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.dataset.view)return await loadView(b.dataset.view);
 const a=b.dataset.act,id=Number(b.dataset.id);if(!a)return;
 if(a==='retry')return boot();if(a==='close')return $('#modal').close();if(a==='menu')return $('.sidebar').classList.toggle('open');
 if(a==='navigate')return loadView(b.dataset.to);
 if(a==='logout'){await api('logout',{});me=null;cache={};currentPatient=null;formHandler=null;clearTimeout(lockTimer);routeVersion++;$('#modal').close();$('#modal').innerHTML='';$('#print').innerHTML='';return auth()}
 if(a==='notifications'){if(me.views.includes('inventory')){await loadView('inventory');toast('ดูสินค้าใกล้หมดและ Lot ใกล้หมดอายุได้ในหน้านี้')}else if(me.views.includes('appointments')){await loadView('appointments');tab='followup';render()}else toast('ไม่มีการแจ้งเตือนเพิ่มเติมสำหรับบทบาทนี้');return;}
 if(a==='tab'){tab=b.dataset.tab;page=1;query='';filter='';render();return;}
 if(a==='page'){page+=Number(b.dataset.step);render();return;}
 if(a==='clear-filter'){filter='';render();return;}
 if(a==='patient')return patientDetail(id);
 if(a==='new-patient')return form('เพิ่มผู้รับบริการ',field('hn','เลข HN')+field('name','ชื่อ–นามสกุล')+field('nickname','ชื่อเล่น','text','',{optional:true})+field('age','อายุ (ปี)','number','',{min:0,max:125,optional:true})+field('phone','เบอร์โทรศัพท์','tel','',{optional:true}),d=>api('patients',d));
 if(a==='member')return form('เปลี่ยนระดับสมาชิก',select('member','ระดับสมาชิก',['Standard','Silver','Gold','Platinum'],currentPatient.member),d=>api('patients/member',{...d,patient_id:id}));
 if(a==='clinical-review'){const p=currentPatient;return form('ทบทวนประวัติสุขภาพ',field('allergies','ประวัติแพ้ยา (ระบุ “ไม่มี” เมื่อยืนยันแล้ว)','textarea',p.allergies,{required:'required'})+field('conditions','โรคประจำตัว (ระบุ “ไม่มี” เมื่อยืนยันแล้ว)','textarea',p.conditions,{required:'required'})+field('medicines','ยาที่รับประทาน','textarea',p.medicines)+field('address','ที่อยู่','textarea',p.address)+field('emergency','ผู้ติดต่อฉุกเฉิน','text',p.emergency,{optional:true}),d=>api('clinical/review',{...d,patient_id:id}));}
 if(a==='consent')return form('บันทึกความยินยอม',select('purpose','วัตถุประสงค์',['การรักษา','ภาพก่อน–หลัง'])+select('decision','การตัดสินใจ',['ยินยอม','ถอนความยินยอม'])+field('signed_by','ชื่อผู้ให้ความยินยอม')+field('version','เลขเวอร์ชัน / อ้างอิงเอกสาร')+'<p class="field full checknote">บันทึกตามเอกสารที่ลงนามจริง เก็บเอกสารต้นฉบับตามนโยบายคลินิก ระบบนี้เก็บข้อมูลอ้างอิง ไม่ใช่ลายเซ็นอิเล็กทรอนิกส์</p>',d=>api('clinical/consent',{...d,patient_id:id}));
 if(a==='photo')return form('เพิ่มภาพก่อน–หลัง',select('phase','ประเภทภาพ',['ก่อนทำ','หลังทำ'])+field('image','ภาพ JPG / PNG ไม่เกิน 2.5 MB','file','',{accept:'image/jpeg,image/png'})+field('note','บันทึกตำแหน่ง / ครั้งที่ทำ','textarea'),async(d,f)=>{const file=f.image.files[0];if(!file||file.size>2500000)throw new Error('เลือกภาพขนาดไม่เกิน 2.5 MB');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file)});return api('clinical/photo',{...d,image:data,patient_id:id})});
 if(a==='new-appointment')return newAppointment();
 if(a==='appointment-status'){const r=cache.appointments.find(x=>x.id===id);return form('สถานะนัดหมาย',select('status','สถานะ',['รอยืนยัน','ยืนยันแล้ว','รอพบแพทย์','กำลังรับบริการ','เสร็จสิ้น','ยกเลิก'],r.status),d=>api('appointments/status',{...d,id}));}
 if(a==='followup'){const r=cache.appointments.find(x=>x.id===id);return form('บันทึกติดตามหลังทำ',field('followup_note','ผลการติดตาม / อาการ / การนัดครั้งถัดไป','textarea',r.followup_note,{required:'required'}),d=>api('appointments/followup',{...d,id}));}
 if(a==='new-procedure')return newProcedure();if(a==='add-item')return addItem();if(a==='remove-item')return b.closest('.inline-items').remove();
 if(a==='procedure-detail'){const r=cache.procedures.find(x=>x.id===id);return modal(esc(r.service),`<p>${esc(r.name)} · ${date(r.created)}</p><div class="detailsection"><h3>บันทึกการรักษา</h3></div><p style="white-space:pre-wrap">${esc(r.note)}</p><div class="detailsection"><h3>ผลิตภัณฑ์ที่ใช้</h3></div>${table(['ผลิตภัณฑ์','Lot','วันหมดอายุ','จำนวน'],r.lots.map(l=>[esc(l.name),esc(l.lot),date(l.expiry),l.qty]))}<p class="checknote">แพทย์ ${esc(r.doctor)} · ผู้ช่วย ${esc(r.nurse)||'—'}</p>`);}
 if(a==='new-package')return form('เพิ่มคอร์สของผู้รับบริการ',select('patient_id','ผู้รับบริการ',await pickPatients())+field('name','ชื่อคอร์ส')+field('total','จำนวนครั้ง','number',5,{min:1,step:1})+field('price','ราคาคอร์ส (บาท)','number','',{min:0,step:'.01'})+field('expiry','วันหมดอายุ','date','',{min:localDate()})+'<p class="field full checknote">การเพิ่มคอร์สไม่ลงรายรับซ้ำ กรุณาออกใบเสร็จหรืออ้างอิงรายรับเดิมในส่วนการเงิน</p>',d=>api('packages',d));
 if(a==='redeem')return form('ใช้สิทธิ์คอร์ส',field('qty','จำนวนครั้งที่ใช้','number',1,{min:1,step:1})+field('reason','หัตถการ / เอกสารอ้างอิง','textarea','',{required:'required'}),d=>api('packages/redeem',{...d,id}));
 if(a==='new-promo')return form('เพิ่มโปรโมชั่น',field('name','ชื่อโปรโมชั่น')+field('discount','ส่วนลด (%)','number',10,{min:0,max:100,step:'.01'})+field('start','เริ่มวันที่','date',localDate())+field('end','สิ้นสุดวันที่','date')+field('terms','เงื่อนไขการใช้สิทธิ์','textarea','',{required:'required'}),d=>api('packages/promotion',d));
 if(a==='receive')return receive();
 if(a==='opening-stock'){const p=cache.inventory.products.find(x=>x.id===id);return form('แก้ยอดตั้งต้นที่ยังไม่ระบุ Lot',`<p class="field full">${esc(p.name)} · ยอดเดิม ${count(p.opening)} ${esc(p.unit)}</p>`+field('opening','ยอดตั้งต้นที่ถูกต้อง (ไม่รวมยอดใน Lot)','number',Math.max(0,p.opening),{min:0,step:'any'})+field('reason','เหตุผล / เอกสารการตรวจนับ','textarea','',{required:'required'}),d=>api('inventory/opening',{...d,product_id:id}));}
 if(a==='new-product')return form('เพิ่มสินค้า',field('code','รหัสสินค้า')+field('name','ชื่อสินค้า')+field('category','หมวดหมู่')+field('unit','หน่วยนับ')+field('min_stock','แจ้งเตือนเมื่อคงเหลือไม่เกิน','number',5,{min:0,step:'any'}),d=>api('inventory/product',d));
 if(a==='adjust-lot')return form('ปรับสินค้าออกจาก Lot',field('qty','จำนวนที่ปรับออก','number',1,{min:.001,step:'any'})+field('reason','เหตุผล (เช่น หมดอายุ / ชำรุด)','textarea','',{required:'required'}),d=>api('inventory/adjust',{...d,lot_id:id}));
 if(a==='new-finance')return newFinance();
 if(a==='convert'){const r=cache.finance.find(x=>x.id===id);return form('ยืนยันรับชำระเงิน',`<p class="field full">${esc(r.customer)} · ${esc(r.description)}<br>ยอดรับชำระ <b>${money(r.amount)}</b></p><label class="checkrow field full"><input type="checkbox" required>ได้รับชำระเงินจริงครบตามยอดแล้ว</label>`,()=>api('finance/convert',{id}),'ออกใบเสร็จ');}
 if(a==='print')return printDoc(cache.finance.find(x=>x.id===id));
 if(a==='export-finance'){const rs=cache.finance.filter(x=>x.kind===tab&&matches(x)&&(!filter||x.date.startsWith(filter)));downloadCSV(rs.map(r=>[docno(r),r.date,r.customer,r.description,r.amount]),['เลขที่','วันที่','ผู้รับบริการ/ผู้รับเงิน','รายการ','ยอดเงิน'],'yuna-'+tab+'.csv');return toast('ส่งออกไฟล์แล้ว');}
 if(a==='new-user')return form('เพิ่มผู้ใช้งาน',field('name','ชื่อผู้ใช้งาน')+field('username','ชื่อสำหรับเข้าสู่ระบบ')+select('role','บทบาท',['Owner','แพทย์','พยาบาล','Front','คลัง','บัญชี'])+field('password','รหัสผ่าน (อย่างน้อย 12 ตัวอักษร)','password','',{minlength:12,autocomplete:'new-password'}),d=>api('users',d));
 if(a==='toggle-user')return form('เปลี่ยนสถานะบัญชี',`<p class="field full">บัญชี ${esc(cache.users.find(u=>u.id===id).name)} จะเปลี่ยนสถานะ และการเข้าสู่ระบบเดิมจะสิ้นสุดทันที</p>`,()=>api('users/toggle',{id}),'ยืนยัน');
 if(a==='reset-password')return form('ตั้งรหัสผ่านใหม่',field('password','รหัสผ่านใหม่ (อย่างน้อย 12 ตัวอักษร)','password','',{minlength:12,autocomplete:'new-password'}),async d=>{await api('users/password',{...d,id});if(id===me.id){me=null;await auth()}});
 }catch(err){toast(err.message)}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;query=e.target.value;page=1;render();const input=$('#search');input.focus();input.setSelectionRange(pos,pos)}});
document.addEventListener('change',async e=>{const id=e.target.id;try{if(id==='dashboard-month'){month=e.target.value||localDate().slice(0,7);await loadView(view,true)}if(['finance-month','fees-month'].includes(id)){month=e.target.value||localDate().slice(0,7);render()}if(['date-filter','month-filter'].includes(id)){filter=e.target.value;page=1;render()}}catch(err){toast(err.message)}});
window.addEventListener('afterprint',()=>$('#print').innerHTML='');
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&me&&Date.now()>=lockDeadline)lockWorkspace()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('.sidebar')?.classList.remove('open')});
boot();
